import React, { useState } from 'react';
import ContentWrapper from '../../../components/ui/ContentWrapper/ContentWrapper';
import InputField from '../../../components/ui/InputField/InputField';
import TextareaField from '../../../components/ui/TextareaField/TextareaField';
import Button from '../../../components/ui/Button/Button';
import FileUpload from '../../../components/ui/FileUpload/FileUpload';
import api from '../../../api/api';

const SendSocialProofPage = ({ user }) => {
  const [formData, setFormData] = useState({ title: '', description: '' });
  const [file, setFile] = useState(null);

  const handleChange = (e) => {
    const { name, value } = e.target;
    setFormData(prev => ({ ...prev, [name]: value }));
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    try {
      const dataToSend = {
        ...formData,
        userId: user.id,
        ongId: user.ong_id,
      };
      await api.post('/proofs', dataToSend);
      alert('Prova social enviada para análise com sucesso!');
      setFormData({ title: '', description: '' });
    } catch (error) {
      console.error("Erro ao enviar prova social:", error);
      alert("Ocorreu um erro ao enviar a sua prova.");
    }
  };

  return (
    <ContentWrapper title="Enviar Prova Social">
      <form onSubmit={handleSubmit}>
        <InputField label="Título da Ação" name="title" value={formData.title} onChange={handleChange} />
        <TextareaField label="Descreva a atividade" name="description" value={formData.description} onChange={handleChange} />
        <FileUpload label="Comprovante" onFileSelect={setFile} />
        <div style={{maxWidth: '300px', marginTop: '2rem'}}>
            <Button type="submit">Enviar para Análise</Button>
        </div>
      </form>
    </ContentWrapper>
  );
};

export default SendSocialProofPage;
